Here's a Redis caching implementation:

```typescript
import Redis from 'ioredis';

const redis = new Redis(process.env.REDIS_URL);

// Cache middleware
function cache(ttl = 3600) {
  return async (req, res, next) => {
    const key = `cache:${req.originalUrl}`;

    const cached = await redis.get(key);
    if (cached) {
      return res.json(JSON.parse(cached));
    }

    // Store original json method
    const originalJson = res.json.bind(res);
    res.json = (data) => {
      redis.setex(key, ttl, JSON.stringify(data));
      return originalJson(data);
    };

    next();
  };
}

// Usage
app.get('/api/posts', cache(300), async (req, res) => {
  const posts = await Post.findAll();
  res.json(posts);
});
```

Here are cache invalidation patterns:

```typescript
// Invalidate specific key
async function invalidateCache(pattern: string) {
  const keys = await redis.keys(pattern);
  if (keys.length > 0) {
    await redis.del(...keys);
  }
}

// After creating/updating posts
app.post('/api/posts', async (req, res) => {
  const post = await Post.create(req.body);
  await invalidateCache('cache:/api/posts*');
  res.json(post);
});

// Or use pub/sub for distributed systems
redis.publish('cache:invalidate', '/api/posts');
```
